events.command:
API_KEY=$(cat "$GALAXY_API_KEY_FILE")

python3 -c "
import bioblend.galaxy
import json

gi = bioblend.galaxy.GalaxyInstance(url='https://usegalaxy.org', key='$API_KEY')
hist_id = 'bbd44e69cb8906b50266f758842da12f'

# Try to submit the Filter Tabular tool
tool_id = 'toolshed.g2.bx.psu.edu/repos/iuc/filter_tabular/filter_tabular/3.3.1'
inputs = {
    'input': {'src': 'hda', 'id': 'f9cad7b01a4721353af9e61eeea16415'},
    'comment_char': 'true',
    'linefilters': [
        {
            'filter': {
                'filter_type': 'regex',
                'regex_pattern': r'^\d+,1,1:0',
                'regex_action': 'include_match'
            }
        }
    ]
}

try:
    result = gi.tools.run_tool(hist_id, tool_id, inputs)
    print('Success:', json.dumps(result, indent=2)[:1000])
except Exception as e:
    print(f'Error: {e}')
    # Try with different input format
    try:
        result = gi.tools.run_tool(hist_id, tool_id, inputs, input_format='21.01')
        print('Success with 21.01:', json.dumps(result, indent=2)[:1000])
    except Exception as e2:
        print(f'Error with 21.01: {e2}')
        # Try legacy format
        try:
            result = gi.tools.run_tool(hist_id, tool_id, inputs, input_format='legacy')
            print('Success with legacy:', json.dumps(result, indent=2)[:1000])
        except Exception as e3:
            print(f'Error with legacy: {e3}')
" 2>&1

